/* KNEIPENQUIZ_V06 */
.player-gate{max-width:540px;margin:24px auto;padding:30px;display:grid;gap:13px}
.player-gate h2{font-size:clamp(1.65rem,4vw,2.45rem);margin:4px 0 0}
.player-gate p{color:var(--muted);margin:0;line-height:1.5}
.player-gate label{display:grid;gap:7px;color:var(--muted);font-size:.91rem}
.player-gate button{width:100%;min-height:46px}
.gate-divider{text-align:center;color:var(--muted);font-size:.83rem;margin:5px 0}
.player-gate .profile-error{color:#ff9292;background:rgba(255,100,100,.09);border:1px solid rgba(255,100,100,.35);padding:11px;border-radius:12px}
.player-gate .gate-note{font-size:.79rem;color:var(--muted)}
.player-toolbar{padding:15px 19px;display:flex;align-items:center;justify-content:space-between;gap:12px;margin:14px 0}
.player-toolbar .toolbar-label{font-size:.76rem;color:var(--muted);display:block}
.player-toolbar strong{font-size:1.16rem;display:block}
.player-toolbar small{display:block;color:var(--muted);margin-top:3px}
.toolbar-buttons{display:flex;gap:8px;flex-wrap:wrap}
.setup label.unseen-option{display:flex;align-items:center;gap:10px;margin:14px 0;color:var(--text);font-weight:700}
.unseen-option input{width:21px;height:21px;accent-color:var(--accent)}
.hint-row{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-top:13px;color:var(--muted);font-size:.85rem}
.hint-row button{padding:9px 13px}
.section-head{display:flex;align-items:center;gap:18px;margin:4px 0 18px}.section-head h2{margin:0}
.stats-detail-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}
.stats-explanation{margin-top:14px;padding:20px;color:var(--muted);line-height:1.55}
.stats-explanation h3{color:var(--text);margin:0 0 8px}.stats-explanation p{margin:8px 0}
